#include <iostream>
#include <iomanip> // For setting output precision and alignment

using namespace std;

int main() {
    double baseA, baseB, height;
    double area;

    // Prompt the user for input
    cout << "=== Trapezoid Area Calculator ===" << endl << endl;
    cout << "Please enter the following values:" << endl;

    cout << "Enter the length of the longer base: ";
    if (!(cin >> baseA)) {
        cerr << "Error: Invalid input for base A. Please enter a numeric value." << endl;
        return 1;
    }

    cout << "Enter the length of the shorter base: ";
    if (!(cin >> baseB)) {
        cerr << "Error: Invalid input for base B. Please enter a numeric value." << endl;
        return 1;
    }

    cout << "Enter the height: ";
    if (!(cin >> height)) {
        cerr << "Error: Invalid input for height. Please enter a numeric value." << endl;
        return 1;
    }

    // Validate that dimensions are positive
    if (baseA <= 0 || baseB <= 0 || height <= 0) {
        cerr << "Error: All dimensions must be greater than zero." << endl;
        return 1;
    }

    // Calculate the area: Area = (baseA + baseB) * height / 2
    area = (baseA + baseB) * height / 2.0;

    // Output the results in a user-friendly format
    cout << endl;
    cout << "-----------------------------" << endl;
    cout << "      CALCULATION RESULTS    " << endl;
    cout << "-----------------------------" << endl;
    cout << "Longer base (a):    " << fixed << setprecision(2) << baseA << " units" << endl;
    cout << "Shorter base (b):   " << fixed << setprecision(2) << baseB << " units" << endl;
    cout << "Height (h):         " << fixed << setprecision(2) << height << " units" << endl;
    cout << "-----------------------------" << endl;
    cout << "Calculated Area:    " << fixed << setprecision(2) << area << " square units" << endl;
    cout << "-----------------------------" << endl;

    return 0;
}
